function leastOpsExpressTarget(x, target) {
  const memo = new Map();

  function termCost(power) {
    return power === 0 ? 2 : power;
  }

  function solve(power, value) {
    if (value === 0) {
      return 0;
    }
    if (value === 1) {
      return termCost(power);
    }
    const key = power + ':' + value;
    if (memo.has(key)) {
      return memo.get(key);
    }
    const digit = value % x;
    const rest = (value - digit) / x;
    let best = digit * termCost(power) + solve(power + 1, rest);
    if (digit > 0) {
      const borrow = (x - digit) * termCost(power) + solve(power + 1, rest + 1);
      best = Math.min(best, borrow);
    }
    memo.set(key, best);
    return best;
  }

  return solve(0, target) - 1;
}

