function leastOpsExpressTarget(x, target) {
  // Shortest path over values: each step adds or subtracts one term x^e,
  // costing its sign plus the operators inside it (x/x for e = 0, e - 1 products otherwise).
  const limit = 2 * x * target + x;
  const moves = [];
  for (let e = 0, p = 1; p <= limit; e++, p *= x) moves.push([p, e === 0 ? 2 : e]);
  const dist = new Map([[0, 0]]);
  const buckets = [[0]];
  for (let d = 0; d < buckets.length; d++) {
    const bucket = buckets[d];
    if (!bucket) continue;
    for (const v of bucket) {
      if (dist.get(v) !== d) continue;
      if (v === target) return d - 1;
      for (const [p, c] of moves) {
        for (const w of [v + p, v - p]) {
          if (Math.abs(w) > limit) continue;
          const nd = d + c;
          if (dist.has(w) && dist.get(w) <= nd) continue;
          dist.set(w, nd);
          if (!buckets[nd]) buckets[nd] = [];
          buckets[nd].push(w);
        }
      }
    }
  }
  return -1;
}

