function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const x = rand() < 0.4 ? pick(2, 6) : pick(2, 100);
    let target = pick(10000000, 200000000);
    if (rand() < 0.25) {
      let power = 1;
      while (power * x <= 200000000) power *= x;
      target = Math.max(1, Math.min(200000000, power + pick(-3, 3)));
    }
    return [x, target];
  }
  const x = rand() < 0.75 ? pick(2, 9) : pick(10, 100);
  let target = pick(1, 400);
  if (rand() < 0.3) {
    let power = 1;
    const steps = pick(0, 4);
    for (let i = 0; i < steps && power * x <= 400; i++) power *= x;
    target = Math.max(1, power + pick(-2, 2));
  }
  return [x, target];
}
